#!/usr/bin/env bash
# shellcheck shell=bash disable=SC2034 # site lists are consumed by the sourcing scripts
#
# nginx helpers shared by bootstrap.sh, certs.sh, basic-auth.sh, uninstall.sh and lint.sh.
# Requires lib/common.sh to be sourced first.
#
# Layout on the host (everything ours is named desyn*):
#   /etc/nginx/sites-available/desyn-*.conf   server blocks + http-level definitions (symlinked in sites-enabled)
#   /etc/nginx/desyn/snippets/*.conf          static snippets from the repo (replaced on every install)
#   /etc/nginx/desyn/local/*.conf             host-specific generated files (never overwritten once present)
#   /etc/nginx/desyn.htpasswd                 basic-auth users (bootstrap.sh)

DESYN_NGINX_ETC="${DESYN_NGINX_ETC:-/etc/nginx}"
DESYN_NGINX_BASE_SITES=(desyn-00-common.conf desyn-acme.conf)
DESYN_NGINX_TLS_SITES=(desyn-landing.conf desyn-app.conf desyn-docs.conf desyn-render.conf)
# Server blocks of the former self-hosted Convex setup (convex., convex-site., dash.). Hosted production uses
# Convex Cloud; certs.sh and uninstall.sh remove these if an older install left them behind.
DESYN_NGINX_RETIRED_SITES=(desyn-convex.conf desyn-dash.conf)
# Host-specific files in /etc/nginx/desyn/local that the server blocks include (bootstrap.sh writes missing ones).
DESYN_NGINX_LOCAL_FILES=(auth-switch.conf gate.conf trusted.geo listen-80.conf listen-443.conf brotli.conf resolver.conf)
DESYN_RESOLV_CONF="${DESYN_RESOLV_CONF:-/etc/resolv.conf}"

nginx_version() {
  nginx -v 2>&1 | sed -n 's#.*nginx/\([0-9.]*\).*#\1#p'
}

# version_ge A B: true when version A >= version B.
version_ge() {
  [[ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | head -n 1)" == "$2" ]]
}

# nginx_user: the worker user from the running configuration (www-data on Ubuntu).
nginx_user() {
  local u
  u="$(nginx -T 2>/dev/null | awk '$1 == "user" { gsub(/;/, "", $2); print $2; exit }')"
  printf '%s' "${u:-www-data}"
}

host_has_ipv6() {
  [[ -r /proc/net/if_inet6 ]] && grep -qv ' lo$' /proc/net/if_inet6
}

# existing_443_uses_http2_listen: another site already enables http2 through the listen directive.
existing_443_uses_http2_listen() {
  nginx -T 2>/dev/null | grep -qE '^\s*listen\s+[^;]*443[^;]*\bhttp2\b'
}

# render_listen_snippets OUTDIR NGINX_VERSION IPV6(0|1) HTTP2_MODE(directive|listen|none)
render_listen_snippets() {
  local out=$1 version=$2 ipv6=$3 mode=$4
  {
    echo "# Generated by bootstrap.sh for nginx ${version} (ipv6=${ipv6})."
    echo "listen 80;"
    if [[ "${ipv6}" == "1" ]]; then echo "listen [::]:80;"; fi
  } >"${out}/listen-80.conf"
  {
    echo "# Generated by bootstrap.sh for nginx ${version} (ipv6=${ipv6}, http2=${mode})."
    case "${mode}" in
      listen)
        echo "listen 443 ssl http2;"
        if [[ "${ipv6}" == "1" ]]; then echo "listen [::]:443 ssl http2;"; fi
        ;;
      *)
        echo "listen 443 ssl;"
        if [[ "${ipv6}" == "1" ]]; then echo "listen [::]:443 ssl;"; fi
        ;;
    esac
    if [[ "${mode}" == "directive" ]]; then echo "http2 on;"; fi
  } >"${out}/listen-443.conf"
}

# detect_http2_mode NGINX_VERSION: server-scoped `http2 on;` on nginx >= 1.25.1; on older nginx the listen
# flag changes the whole shared socket, so it is only used when another site already enabled it.
detect_http2_mode() {
  local version=$1
  if version_ge "${version}" "1.25.1"; then
    echo directive
  elif existing_443_uses_http2_listen; then
    echo listen
  else
    echo none
  fi
}

render_auth_switch() {
  local out=$1 prelaunch=$2
  cat >"${out}/auth-switch.conf" <<EOF
# SWITCH: 1 = pre-launch (HTTP basic auth on desyn.app, app. and docs.), 0 = launched (public).
# Change with: deploy/scripts/basic-auth.sh on|off   (validates with nginx -t, then reloads)
map \$host \$desyn_prelaunch {
    default ${prelaunch};
}
EOF
}

render_gate() {
  local out=$1 token=$2
  (
    umask 077
    cat >"${out}/gate.conf" <<EOF
# Pre-launch gate token. Generated by bootstrap.sh; keep this file root-only (mode 0600).
map \$host \$desyn_gate_token {
    default "${token}";
}
# Regex key: a 64-character literal would exceed the default map_hash_bucket_size, and that directive is
# http-global (setting it here could clash with the host's own configuration).
map \$cookie_desyn_gate \$desyn_gate_cookie_ok {
    default 0;
    "~^${token}\$" 1;
}
EOF
  )
}

# render_trusted OUTDIR CIDR...
render_trusted() {
  local out=$1 cidr
  shift
  {
    echo "# Sources that skip the pre-launch prompt (geo block body). Generated by bootstrap.sh."
    for cidr in "$@"; do
      if [[ -n "${cidr}" ]]; then printf '%s 1;\n' "${cidr}"; fi
    done
  } >"${out}/trusted.geo"
}

# host_nameservers: the nameservers of this host (resolv.conf order), one per line.
host_nameservers() {
  awk '$1 == "nameserver" && $2 != "" { print $2 }' "${DESYN_RESOLV_CONF}" 2>/dev/null || true
}

# render_resolver OUTDIR IPV6(0|1) NAMESERVER...: the resolver nginx uses for proxy_pass targets named by a
# variable (app.desyn.app /api/v1 and /mcp -> the Convex Cloud site URL), so the Convex Cloud addresses are
# re-resolved while nginx runs instead of being pinned at reload time. Returns 1 when no usable nameserver is left.
render_resolver() {
  local out=$1 ipv6=$2 ns servers=()
  shift 2
  for ns in "$@"; do
    # Link-local addresses with a zone (fe80::1%eth0) cannot be used by nginx.
    [[ -z "${ns}" || "${ns}" == *%* ]] && continue
    if [[ "${ns}" == *:* ]]; then
      [[ "${ipv6}" == "1" ]] || continue
      servers+=("[${ns}]")
    else
      servers+=("${ns}")
    fi
  done
  ((${#servers[@]})) || return 1
  local flags="valid=60s"
  [[ "${ipv6}" == "1" ]] || flags+=" ipv6=off"
  cat >"${out}/resolver.conf" <<EOF
# DNS for proxy targets named by a variable (the Convex Cloud site URL), re-resolved every 60 s.
# Generated by bootstrap.sh from ${DESYN_RESOLV_CONF}.
resolver ${servers[*]} ${flags};
resolver_timeout 5s;
EOF
}

# render_brotli OUTDIR ENABLED(0|1)
render_brotli() {
  local out=$1 enabled=$2
  if [[ "${enabled}" == "1" ]]; then
    cat >"${out}/brotli.conf" <<'EOF'
# brotli module detected by bootstrap.sh.
brotli on;
brotli_comp_level 5;
brotli_min_length 1024;
brotli_types text/plain text/css text/xml text/javascript application/javascript application/json
             application/xml application/rss+xml application/atom+xml application/manifest+json
             application/wasm image/svg+xml font/ttf font/otf;
EOF
  else
    echo "# brotli module not loaded on this host; gzip (desyn/snippets/compression.conf) is used." >"${out}/brotli.conf"
  fi
}

nginx_has_brotli() {
  nginx -V 2>&1 | grep -q 'brotli' && return 0
  ls /etc/nginx/modules-enabled/*brotli* >/dev/null 2>&1
}

# install_nginx_snippets DEPLOY_DIR: copy static snippets to /etc/nginx/desyn/snippets.
install_nginx_snippets() {
  local deploy_dir=$1 f
  run install -d -m 0755 "${DESYN_NGINX_ETC}/desyn" "${DESYN_NGINX_ETC}/desyn/snippets" "${DESYN_NGINX_ETC}/desyn/local"
  for f in "${deploy_dir}"/nginx/desyn/snippets/*.conf; do
    install_managed_file "${f}" "${DESYN_NGINX_ETC}/desyn/snippets/$(basename "${f}")" 0644
  done
}

# install_nginx_sites DEPLOY_DIR SITE...: copy server blocks and enable them.
install_nginx_sites() {
  local deploy_dir=$1 site
  shift
  for site in "$@"; do
    install_managed_file "${deploy_dir}/nginx/sites-available/${site}" "${DESYN_NGINX_ETC}/sites-available/${site}" 0644
    if [[ ! -L "${DESYN_NGINX_ETC}/sites-enabled/${site}" ]]; then
      run ln -s "${DESYN_NGINX_ETC}/sites-available/${site}" "${DESYN_NGINX_ETC}/sites-enabled/${site}"
    fi
  done
}

disable_nginx_sites() {
  local site
  for site in "$@"; do
    if [[ -L "${DESYN_NGINX_ETC}/sites-enabled/${site}" ]]; then
      run rm -f "${DESYN_NGINX_ETC}/sites-enabled/${site}"
    fi
  done
}

# remove_retired_nginx_files: disable and delete server blocks and snippets that earlier versions installed
# (self-hosted Convex hosts). Callers validate and reload afterwards.
remove_retired_nginx_files() {
  local site snippet
  for site in "${DESYN_NGINX_RETIRED_SITES[@]}"; do
    disable_nginx_sites "${site}"
    if [[ -f "${DESYN_NGINX_ETC}/sites-available/${site}" ]]; then
      run rm -f "${DESYN_NGINX_ETC}/sites-available/${site}"
      info "removed retired ${site}"
    fi
  done
  for snippet in auth-api.conf auth-actions.conf csp-api.conf csp-dash.conf; do
    if [[ -f "${DESYN_NGINX_ETC}/desyn/snippets/${snippet}" ]]; then run rm -f "${DESYN_NGINX_ETC}/desyn/snippets/${snippet}"; fi
  done
}

# nginx_test_and_reload: validate the whole configuration, reload only when valid.
nginx_test_and_reload() {
  if [[ "${DRY_RUN}" == "1" ]]; then
    info "[dry-run] would run nginx -t and systemctl reload nginx"
    return 0
  fi
  local out
  if ! out="$(nginx -t 2>&1)"; then
    printf '  nginx: %s\n' "${out//$'\n'/$'\n'  nginx: }" >&2
    return 1
  fi
  # Explicit: callers use this in `if !`, where errexit does not apply, so a failed reload must not report ok.
  if ! systemctl reload nginx; then
    error "nginx -t passed but systemctl reload nginx failed (systemctl status nginx)"
    return 1
  fi
  ok "nginx reloaded"
}

nginx_sites_dir_layout_ok() {
  [[ -d "${DESYN_NGINX_ETC}/sites-available" && -d "${DESYN_NGINX_ETC}/sites-enabled" ]] || return 1
  nginx -T 2>/dev/null | grep -qE 'include\s+/etc/nginx/sites-enabled/\*'
}
